            rb_last = rb[-1]

            # Option A: append rb to ra (ra_last==i and rb_first==j)
            if ra_last == i and rb_first == j and can_merge(ra, rb, i, j):
                new_route = ra + rb
            # Option B: append ra to rb (rb_last==j and ra_first==i)
            elif rb_last == j and ra_first == i and can_merge(ra, rb, i, j):
                new_route = rb + ra
            # Option C: append rb to ra reversed (ra_last==i and rb_last==j) => ra + reversed(rb)
            elif ra_last == i and rb_last == j and can_merge(ra, rb, i, j):
                new_route = ra + rb[::-1]
            # Option D: append ra to rb reversed (rb_first==j and ra_first==i) => reversed(ra)+rb
            elif rb_first == j and ra_first == i and can_merge(ra, rb, i, j):
                new_route = ra[::-1] + rb
            else:
                continue

            # merge deterministically: keep longer route index? We'll deactivate both and create new at ra_idx
            # Reuse ra_idx slot
            route_list[ra_idx] = new_route
            active[rj_idx] = False
            # Update route_of for all customers in rb
            for v in rb:
                route_of[v] = ra_idx

        # Collect active routes (remove empties)
        res = []
        for k in range(len(route_list)):
            if active[k] and route_list[k]:
                res.append(route_list[k])
        return res

    def inter_route_repair(routes):
        # Ensure all customers are present and capacity-feasible by deterministic relocation.
        # If anything missing due to construction issues, reinsert greedily.
        all_in_routes = set()
        for r in routes:
            for v in r:
                all_in_routes.add(v)
        missing = [v for v in customers if v not in all_in_routes]
        if missing:
            # Insert missing into best feasible route, else create new route
            for v in sorted(missing):
                best = None
                best_delta = None
                for ridx, r in enumerate(routes):
                    if route_load(r) + demands[v] > capacity:
                        continue
                    # Try best insertion position (including ends) deterministically
                    m = len(r)
                    # insertion at position p between r[p-1] and r[p], p in [0..m]
                    for p in range(m + 1):
                        if p == 0:
                            delta = matrix[depot][v] + matrix[v][r[0]] - matrix[depot][r[0]]
                        elif p == m:
                            delta = matrix[depot][r[m - 1]] + matrix[r[m - 1]][v] - matrix[depot][r[m - 1]]
                        else:
                            a = r[p - 1]
                            b = r[p]
                            delta = matrix[a][v] + matrix[v][b] - matrix[a][b]
                        if best_delta is None or delta < best_delta or (delta == best_delta and ridx < best):
                            best_delta = delta
                            best = (ridx, p)
                if best is None:
                    # create new route
                    routes.append([v])
                else:
                    ridx, p = best
                    routes[ridx].insert(p, v)

        # Repair any capacity violations (shouldn't happen, but keep safe):
        # while exists a violating route, move its last customer to best feasible place elsewhere.
        changed = True
        while changed:
            changed = False
            for ridx in range(len(routes)):
                r = routes[ridx]
                if route_load(r) <= capacity:
                    continue
                # move customers from end until feasible or empty
                while r and route_load(r) > capacity:
                    v = r[-1]
                    best = None
                    best_delta = None
                    for oridx in range(len(routes)):
                        if oridx == ridx:
                            continue
                        orr = routes[oridx]
                        if route_load(orr) + demands[v] > capacity:
                            continue
                        m = len(orr)
                        for p in range(m + 1):
                            if p == 0:
                                delta = matrix[depot][v] + matrix[v][orr[0]] - matrix[depot][orr[0]]
                            elif p == m:
                                delta = matrix[depot][orr[m - 1]] + matrix[orr[m - 1]][v] - matrix[depot][orr[m - 1]]
                            else:
                                a = orr[p - 1]
                                b = orr[p]
                                delta = matrix[a][v] + matrix[v][b] - matrix[a][b]
                            if best_delta is None or delta < best_delta or (delta == best_delta and oridx < best[0]):
                                best_delta = delta
                                best = (oridx, p)
                    if best is None:
                        # can't place; create new route
                        routes.append([v])
                    else:
                        oridx, p = best
                        routes[oridx].insert(p, v)
                    r.pop()
                    changed = True
                if not routes[ridx]:
                    # remove empty route
                    routes.pop(ridx)
                    break
            if changed:
                continue
        return routes

    def two_opt_intra(routes):
        # Deterministic first-improvement 2-opt within each route
        for ridx in range(len(routes)):
            r = routes[ridx]
            m = len(r)
            if m < 4:
                continue
            improved = True
            while improved:
                improved = False
                for i in range(m - 3):
                    a = r[i]
                    b = r[i + 1]
                    for j in range(i + 2, m - 1):
                        c = r[j]
                        d = r[j + 1]
                        cur = matrix[a][b] + matrix[c][d]
                        new = matrix[a][c] + matrix[b][d]
                        if new < cur - 0:  # strict deterministic improvement
                            r[i + 1:j + 1] = reversed(r[i + 1:j + 1])
                            improved = True
                            break
                    if improved:
                        break
        return routes

